import jwt, { JwtPayload, TokenExpiredError } from "jsonwebtoken";
import type { Request, Response, NextFunction } from "express";
import { DriverDirectory } from "./driverDirectory";

export interface DriverTokenConfig {
  publicKey: string;
  issuer: string;
  audience: string;
  clockToleranceSec: number;
}

export interface DriverPrincipal {
  driverId: string;
  sessionId: string;
}

export interface DriverRequest extends Request {
  driver?: DriverPrincipal;
}

function bearerToken(req: Request): string | null {
  const header = req.header("authorization");
  if (!header) return null;
  const [scheme, value] = header.split(" ");
  if (scheme?.toLowerCase() !== "bearer" || !value) return null;
  return value;
}

export function requireDriver(cfg: DriverTokenConfig, directory: DriverDirectory) {
  return async (req: DriverRequest, res: Response, next: NextFunction) => {
    const token = bearerToken(req);
    if (!token) {
      res.setHeader("WWW-Authenticate", "Bearer");
      return res.status(401).json({ error: "missing_token" });
    }

    let claims: JwtPayload;
    try {
      claims = jwt.verify(token, cfg.publicKey, {
        algorithms: ["RS256"],
        issuer: cfg.issuer,
        audience: cfg.audience,
        clockTolerance: cfg.clockToleranceSec,
      }) as JwtPayload;
    } catch (err) {
      const code = err instanceof TokenExpiredError ? "token_expired" : "invalid_token";
      res.setHeader("WWW-Authenticate", `Bearer error="invalid_token"`);
      return res.status(401).json({ error: code });
    }

    if (claims.typ !== "driver" || typeof claims.sub !== "string" || typeof claims.sid !== "string") {
      return res.status(401).json({ error: "invalid_token" });
    }

    try {
      const status = await directory.sessionStatus(claims.sub, claims.sid);
      if (status !== "active") {
        return res.status(401).json({ error: "session_revoked" });
      }
    } catch (err) {
      req.log?.warn({ err }, "driver directory unavailable");
      return res.status(503).json({ error: "auth_unavailable" });
    }

    req.driver = { driverId: claims.sub, sessionId: claims.sid };
    next();
  };
}

import type { Redis } from "ioredis";

export type SessionStatus = "active" | "revoked" | "unknown";

export class DriverDirectory {
  constructor(private readonly redis: Redis) {}

  async sessionStatus(driverId: string, sessionId: string): Promise<SessionStatus> {
    const value = await this.redis.get(`driver:${driverId}:session:${sessionId}`);
    if (value === null) return "unknown";
    return value === "active" ? "active" : "revoked";
  }

  async revoke(driverId: string, sessionId: string): Promise<void> {
    await this.redis.set(`driver:${driverId}:session:${sessionId}`, "revoked", "EX", 86400);
  }
}

import express from "express";
import { readFileSync } from "fs";
import Redis from "ioredis";
import { requireDriver, DriverRequest } from "./requireDriver";
import { DriverDirectory } from "./driverDirectory";
import { dispatch } from "./dispatch";

const cfg = {
  publicKey: readFileSync(process.env.DRIVER_JWT_PUBLIC_KEY_PATH!, "utf8"),
  issuer: "https://auth.rides.internal",
  audience: "dispatch-api",
  clockToleranceSec: 30,
};

const directory = new DriverDirectory(new Redis(process.env.REDIS_URL!));
const app = express();
app.use(express.json());

app.post("/v1/trips/:tripId/accept", requireDriver(cfg, directory), async (req: DriverRequest, res) => {
  const result = await dispatch.acceptTrip(req.params.tripId, req.driver!.driverId);
  if (!result.ok) return res.status(409).json({ error: result.reason });
  res.json(result.trip);
});

app.post("/v1/drivers/me/logout", requireDriver(cfg, directory), async (req: DriverRequest, res) => {
  await directory.revoke(req.driver!.driverId, req.driver!.sessionId);
  res.status(204).end();
});

export default app;
